import React, { useState, useEffect } from 'react';
import {
  TextField, Button, Container, Typography, Paper, Table, TableBody, TableCell,
  TableContainer, TableHead, TableRow, Chip, Box, Alert, CssBaseline, useMediaQuery,
  ThemeProvider, createTheme, Fade, Zoom, Grid, Divider
} from '@mui/material';
import { green, red, blue, grey } from '@mui/material/colors';

const theme = createTheme({
  palette: {
    primary: { main: '#0B3D91' },
    secondary: { main: '#00897B' },
    background: {
      default: '#f4f6f8',
      paper: '#ffffff',
    },
    error: { main: red[700] },
  },
  typography: {
    fontFamily: "'Segoe UI', sans-serif",
    h3: {
      fontWeight: 700,
      color: '#0B3D91',
    },
    h5: {
      fontWeight: 600,
      color: '#333',
    },
    button: {
      textTransform: 'none',
      fontWeight: 600,
    },
  },
  shape: {
    borderRadius: 12,
  },
  components: {
    MuiButton: {
      styleOverrides: {
        root: {
          '&:hover': {
            boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
            backgroundColor: blue[900],
          },
        },
      },
    },
    MuiPaper: {
      styleOverrides: {
        root: {
          boxShadow: '0 6px 20px rgba(0,0,0,0.1)',
          padding: '32px',
        },
      },
    },
  },
});

function App() {
  const [website, setWebsite] = useState('');
  const [monitoringStatus, setMonitoringStatus] = useState('Idle');
  const [threatDetected, setThreatDetected] = useState(false);
  const [message, setMessage] = useState('');
  const [threatLogs, setThreatLogs] = useState([]);

  const isMobile = useMediaQuery(theme.breakpoints.down('md'));

  const startMonitoring = async () => {
    if (!website) {
      setMessage('Please enter a website URL.');
      return;
    }
    setMessage('');
    try {
      const response = await fetch('http://127.0.0.1:5001/start_monitoring', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ website }),
      });
      const data = await response.json();
      if (response.ok) {
        setMessage(data.message);
        setMonitoringStatus('Monitoring');
      } else {
        setMessage(data.error || 'Failed to start monitoring.');
      }
    } catch (error) {
      setMessage('Error connecting to backend.');
    }
  };

  const stopMonitoring = async () => {
    try {
      const response = await fetch('http://127.0.0.1:5001/stop_monitoring', { method: 'POST' });
      if (response.ok) {
        setMonitoringStatus('Idle');
        setThreatDetected(false);
        setThreatLogs([]);
        setMessage('Monitoring stopped.');
      } else {
        setMessage('Failed to stop monitoring.');
      }
    } catch (error) {
      setMessage('Error connecting to backend.');
    }
  };

  useEffect(() => {
    setThreatLogs([]);
    let interval = null;

    if (monitoringStatus === 'Monitoring') {
      interval = setInterval(async () => {
        try {
          const response = await fetch('http://127.0.0.1:5001/status');
          const data = await response.json();
          setMonitoringStatus(data.status);
          setThreatDetected(data.threat_detected);

          const logsResponse = await fetch('http://127.0.0.1:5001/threat_logs');
          const logsData = await logsResponse.json();
          const cleanedLogs = logsData.map(log => {
            let cleanedWebsite = log.website.replace(/^https?:\/\//, '');
            return { ...log, website: cleanedWebsite };
          });
          setThreatLogs(cleanedLogs);
        } catch (error) {
          setMonitoringStatus('Error');
          setThreatDetected(false);
          setThreatLogs([]);
        }
      }, 5000);
    }

    return () => interval && clearInterval(interval);
  }, [monitoringStatus]);

  const getStatusColor = (status) => {
    switch (status) {
      case 'Monitoring': return blue[800];
      case 'Idle': return grey[600];
      default: return grey[600];
    }
  };

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Container maxWidth="lg" sx={{ mt: 6, mb: 6 }}>
        <Typography variant="h3" align="center" gutterBottom>
          Cyber Threat Detection System
        </Typography>
        <Typography variant="h6" align="center" sx={{ mb: 5, color: '#444' }}>
          Real-time Website Monitoring & Threat Intelligence
        </Typography>

        <Grid container spacing={4} direction={isMobile ? 'column' : 'row'}>
          <Grid item xs={12} md={6}>
            <Paper>
              <Box
                component="form"
                onSubmit={(e) => {
                  e.preventDefault();
                  startMonitoring();
                }}
                sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}
              >
                <TextField
                  label="Enter Website URL"
                  variant="outlined"
                  fullWidth
                  value={website}
                  onChange={(e) => setWebsite(e.target.value)}
                  required
                />
                <Box sx={{ display: 'flex', gap: 2 }}>
                  <Button variant="contained" color="primary" type="submit" fullWidth>
                    Start Monitoring
                  </Button>
                  <Button variant="outlined" color="error" onClick={stopMonitoring} fullWidth>
                    Stop
                  </Button>
                </Box>
              </Box>
              {message && (
                <Zoom in>
                  <Alert severity="info" sx={{ mt: 3 }}>{message}</Alert>
                </Zoom>
              )}
              <Divider sx={{ my: 3 }} />
              <Box sx={{ textAlign: 'center' }}>
                <Typography variant="subtitle1" fontWeight={600}>Status:</Typography>
                <Chip
                  label={monitoringStatus}
                  sx={{
                    mt: 1,
                    bgcolor: threatDetected ? red[700] : getStatusColor(monitoringStatus),
                    color: 'white',
                    fontWeight: 'bold',
                    fontSize: 14,
                    px: 3,
                    py: 0.5,
                    borderRadius: 4,
                  }}
                />
                {threatDetected && (
                  <Fade in timeout={600}>
                    <Alert severity="error" sx={{ mt: 3, fontWeight: 'bold' }}>
                      Threat Detected!
                    </Alert>
                  </Fade>
                )}
              </Box>
            </Paper>
          </Grid>

          <Grid item xs={12} md={6}>
            <Paper sx={{ maxHeight: 520, overflowY: 'auto' }}>
              <Typography variant="h5" gutterBottom>
                Detected Threat Logs
              </Typography>
              {threatLogs.length === 0 ? (
                <Typography variant="body2" align="center" sx={{ fontStyle: 'italic', mt: 2 }}>
                  No threats detected yet.
                </Typography>
              ) : (
                <Table stickyHeader>
                  <TableHead>
                    <TableRow>
                      <TableCell>Time</TableCell>
                      <TableCell>Website</TableCell>
                      <TableCell>Threat</TableCell>
                      <TableCell>Message</TableCell>
                      <TableCell>Solution</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {threatLogs.map((log) => (
                      <TableRow key={log.id} hover>
                        <TableCell>{log.timestamp}</TableCell>
                        <TableCell>{log.website}</TableCell>
                        <TableCell>{log.threat_name}</TableCell>
                        <TableCell>{log.message}</TableCell>
                        <TableCell>{log.solution}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </Paper>
          </Grid>
        </Grid>
      </Container>
    </ThemeProvider>
  );
}

export default App;
